const names=Object.fromEntries(categories.map(c=>[c.id,c.title])),initial=()=>({direction:'web',hours:8,tasks:[],jobs:[],applications:[],answers:['','','','',''],ratings:{}});let jobsView='categories',lastSavedJob='',activeCategory='';let recruitmentSync=null,recruitmentScheduleEnabled=false;let categoryBrowse={query:"",scroll:0};
