let crystalCleanup=()=>{},crystalGeneration=0;let state=initial(),page='prep',db,saveText='正在连接本地存储';
try{db=await new Promise((resolve,reject)=>{let r=indexedDB.open('jobpath-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});const saved=await new Promise((resolve,reject)=>{let r=db.transaction('state').objectStore('state').get('main');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(saved)state=validateBackup({app:'jobpath',schemaVersion:1,data:saved});saveText='本机保存';}catch{saveText='临时模式 / 未持久保存';}
