async function save(){pendingSaves++;saveText='正在保存';const snapshot=structuredClone(state);const operation=queue.then(async()=>{if(!db)throw Error('本地存储不可用，请导出备份');revision=await writeRevision(db,snapshot,revision);state.revision=revision;saveFailed=false;saveText='已保存';});queue=operation.catch(()=>{});try{await operation}catch(e){saveFailed=true;saveText='保存失败 / 请备份';toast(e.message);throw e}finally{pendingSaves--;const label=document.querySelector('.footer span:last-child');if(label)label.textContent=saveText+'';}}
