async function aiPreview(mode,payload,onDraft){if(aiPending.has(mode))return;aiPending.add(mode);const requestState=state,stopRadar=mode==='job_match'?startRadar():()=>{};const selector=aiButtons[mode],trigger=(selector&&document.querySelector(selector))||document.activeElement,button=trigger?.tagName==='BUTTON'?trigger:null,original=button?.textContent;let status;if(button){status=button.parentElement.querySelector(':scope > .ai-inline-status');if(!status){status=document.createElement('p');status.className='ai-inline-status';status.setAttribute('role','status');button.after(status)}status.classList.remove('error');status.textContent='正在结合你的目标生成建议…';showAIBusy(mode)}try{const token=sessionStorage.getItem('jobpath-invite')||'';const r=await aiFetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token,'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({mode,payload,consentVersion:'2026-10-16-v1'}),signal:AbortSignal.timeout(25000)});const data=await r.json();if(!r.ok)throw Error(data.message||'AI 暂时不可用');const commit=()=>{if(state!==requestState)throw Error('个人数据已切换，请在当前数据中重新生成');return onDraft(data.data)};const writing=aiDraftWrites.then(commit);aiDraftWrites=writing.catch(()=>{});await writing;if(status?.isConnected)status.textContent='已生成';toast('AI 已完成')}catch(e){const message=e.name==='TimeoutError'?'生成超时，请稍后再试':e.message;if(status?.isConnected){status.textContent=message;status.classList.add('error')}toast(message)}finally{stopRadar();aiPending.delete(mode);const current=(selector&&document.querySelector(selector))||button;if(current?.isConnected){current.disabled=false;current.textContent=current.dataset.aiIdleText||original;delete current.dataset.aiIdleText;current.removeAttribute('aria-busy')}}}

