function savedView(){return `<div class="saved-heading"><h2>收藏岗位</h2></div><p class="muted">集中管理感兴趣的岗位，选择当前备战目标。</p><div class="saved-scopes" role="group" aria-label="收藏范围">${[['active','正在考虑'],['archived','已归档'],['all','全部收藏']].map(([id,label])=>`<button type="button" data-saved-scope="${id}" aria-pressed="${savedFilter.archive===id}">${label} <span class="scope-count" data-scope-count="${id}">0</span></button>`).join('')}</div><div id="current-target"></div><div class="saved-filters"><label>搜索收藏岗位<input id="job-search" type="search" value="${esc(savedFilter.q)}" placeholder="职位、公司、城市、方向"></label><label>我的资格核对<select id="job-qualification">${['','待确认','符合','不符合'].map(v=>`<option value="${v}" ${v===savedFilter.qualification?'selected':''}>${v||'全部资格'}</option>`).join('')}</select></label><label>排序<select id="saved-sort">${[['saved','最近收藏'],['updated','最近更新'],['deadline','截止日期']].map(([v,n])=>`<option value="${v}" ${v===savedFilter.sort?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="saved-results-bar"><span id="saved-count" role="status"></span><button id="clear-saved" class="text-link">清空筛选</button></div><div id="saved-list"></div><div id="filter-empty" class="empty" hidden></div><div id="saved-empty" class="empty" hidden>还没有保存收藏岗位。<button data-explore-jobs>探索岗位</button></div>`}
