function bindSaved(){if(!$('#saved-list'))return;$('#job-search').oninput=$('#job-qualification').onchange=$('#saved-sort').onchange=()=>{savedFilter={...savedFilter,q:$('#job-search').value,qualification:$('#job-qualification').value,sort:$('#saved-sort').value};renderSaved()};$('#clear-saved').onclick=clearSavedFilter;$('#saved-jd-view').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.savedScope){setSavedScope(b.dataset.savedScope);return}if(b.hasAttribute('data-paste-jd'))newJD();if(b.hasAttribute('data-explore-jobs')){$('[data-job-view=categories]').click()}if(b.hasAttribute('data-clear-saved'))clearSavedFilter();if(b.dataset.organize)showSaved(b.dataset.organize);if(b.dataset.editSaved)editSaved(b.dataset.editSaved);if(b.dataset.removeSaved)removeSaved(b.dataset.removeSaved);if(b.dataset.archiveSaved)archiveSaved(b.dataset.archiveSaved)};renderSaved()}
