async function mutateSaved(change,done=()=>{}){if(savedBusy)return;savedBusy=true;const before=structuredClone(state);try{change();await save();renderSaved();updateRecruitmentButtons();updateSavedBadge();done()}catch(e){state=before;renderSaved();updateRecruitmentButtons();toast('保存失败，未更改收藏：'+e.message)}finally{savedBusy=false}}
function updateSavedBadge(){const badge=$('.saved-count');if(badge){const n=savedRecords(state).length;badge.textContent=n;badge.setAttribute('aria-label',n+' 条收藏')}}
function savedFeedback(text,view,undo,viewLabel='查看'){let box=$('#saved-feedback');if(!box){box=document.createElement('div');box.id='saved-feedback';box.setAttribute('role','status');box.className='saved-feedback';$('.opportunity-tools').after(box)}box.replaceChildren(document.createTextNode(text+' · '));for(const [label,fn]of [[viewLabel,view],['撤销',undo]])if(fn){const b=document.createElement('button');b.className='text-link';b.textContent=label;b.onclick=()=>{if(fn===undo)box.remove();fn()};box.append(b)}}
function removeSaved(key,after=()=>{}){const j=actualSaved(key);if(!j)return;const original=structuredClone(j),target=state.targetId===j.id;mutateSaved(()=>{if(key.startsWith('job:'))j.removed=true;else state.recruitmentSaves=state.recruitmentSaves.filter(r=>r.id!==j.id);if(target){state.targetId=null;state.target=''}},()=>{after();savedFeedback(target?'已取消收藏并解除当前目标；既有任务和投递记录保留':'已取消收藏',null,()=>mutateSaved(()=>{if(key.startsWith('job:'))Object.assign(state.jobs.find(x=>x.id===j.id),original,{removed:false});else state.recruitmentSaves.push(original);if(target){state.targetId=j.id;state.target=j.title}},()=>savedFeedback('已恢复收藏',()=>{jobsView='saved';render()},null)))})}
function archiveSaved(key){const j=actualSaved(key);if(!j)return;const original={archived:!!j.archived,updatedAt:j.updatedAt},previousTarget=state.targetId,previousTitle=state.target,target=state.targetId===j.id;mutateSaved(()=>{j.archived=!j.archived;j.updatedAt=Date.now();if(j.archived&&target){state.targetId=null;state.target=''}},()=>savedFeedback(j.archived?'已归档，岗位仍保存在“已归档”中'+(target?'；当前备战目标已解除':''):'已恢复到正在考虑的岗位',()=>setSavedScope(j.archived?'archived':'active',true),()=>mutateSaved(()=>{const current=actualSaved(key);if(!current)return;Object.assign(current,original);if(target&&!state.targetId){state.targetId=previousTarget;state.target=previousTitle}},()=>savedFeedback('已撤销归档操作',()=>setSavedScope(original.archived?'archived':'active',true),null,original.archived?'查看归档':'查看收藏')),j.archived?'查看归档':'查看收藏'))}
function updateRecruitmentButtons(){for(const b of document.querySelectorAll('[data-save-recruit]')){const id=b.dataset.saveRecruit,record=savedRecords(state).find(j=>(j.publicId||j.id)===id);b.textContent=record?'已收藏':'收藏岗位';b.disabled=!!record;b.onclick=()=>saveRecruitment(id);let cancel=b.parentElement.querySelector(`[data-unsave-recruit="${id}"]`);if(record&&!cancel){cancel=document.createElement('button');cancel.className='text-link';cancel.dataset.unsaveRecruit=id;b.after(cancel)}if(cancel){cancel.hidden=!record;cancel.textContent='取消收藏';cancel.onclick=()=>record&&removeSaved(record.key)}}}


function cityDisplay(city){const parts=String(city||'未披露').split(/[、，,]/);return parts.length>2?`<details class="city-expand"><summary>${esc(parts.slice(0,2).join('、'))} 等城市</summary><p>${esc(city)}</p></details>`:`<span>${esc(city||'城市未披露')}</span>`}
function recruitmentCard(r){const d=recruitmentDetail(r);return `<article class="panel recruit-card compact-position"><h3>${esc(r.title)}</h3><div class="compact-meta">${esc(r.company)} · ${cityDisplay(r.city)} · ${esc(r.intent)}</div><p class="compact-condition">${esc(d.qualifications.join('；')||'申请条件未披露')}</p><p class="compact-intro">${esc(d.duties[0]||'仅有部分要求摘录，岗位内容请查看详情。')}</p><div class="compact-actions"><button data-save-recruit="${esc(r.id)}">收藏岗位</button><button class="primary" data-position-open="${esc(r.id)}">查看详情</button></div></article>`}
function openPosition(id){const r=jobsForCategory(activeCategory).find(j=>j.id===id);if(!r)return;const box=$('#category-jobs-view'),scroll=window.scrollY;box.querySelector('.position-detail')?.remove();box.querySelector('.category-top').hidden=true;$('#recruit-results').hidden=true;
 const d=recruitmentDetail(r),list=items=>items.length?`<ul>${items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:'<p class="undisclosed">未披露</p>',grad=d.qualifications.filter(t=>/届|毕业/.test(t)),audience=d.qualifications.filter(t=>!grad.includes(t)),steps=[...new Set([...d.unclassified,...d.skills].filter(t=>/选择.*意向/.test(t)))];
 const section=document.createElement('section');section.className='position-detail';section.innerHTML=`<button class="text-link" id="back-positions">‹ 返回招聘列表</button><h2 tabindex="-1">${esc(r.title)}</h2><div class="compact-meta">${esc(r.company)} · ${cityDisplay(r.city)} · ${esc(r.intent)}</div>
 <div class="position-detail-actions"><button data-save-recruit="${esc(r.id)}">收藏岗位</button><a class="official-action" href="${esc(safeUrl(r.source))}" target="_blank" rel="noopener noreferrer">前往官网 ↗</a></div>
 <details class="summary-help"><summary>招聘官网摘要 ⓘ</summary><p>${d.partial?'仅有部分摘录。':''}摘录不等同于完整 JD；未披露不表示不限，申请条件以官网为准。保留来源中的“或、优先”等关系。</p></details>
 <div class="position-columns"><div class="position-main"><section><h3>岗位内容</h3>${list(d.duties)}</section><section><h3>技能与能力</h3>${list(d.skills.filter(t=>!/选择.*意向/.test(t)))}</section>${steps.length?`<section><h3>申请步骤</h3>${list(steps)}</section>`:''}</div><section class="position-conditions"><h3>申请条件</h3>${audience.length?`<h4>申请对象</h4>${list(audience)}`:''}${grad.length?`<h4>毕业届别${grad.some(t=>/本科|硕士|博士|专业/.test(t))?'与申请对象':''}</h4>${list(grad)}`:''}${!grad.length&&!audience.length?'<p>未披露</p>':''}</section></div>
 <details class="position-evidence"><summary>来源与核验</summary><p>${({open:'核验时有投递入口',closed:'已截止',unknown:'待核验'})[r.hiringStatus||'unknown']} · 检查 ${beijingTime(r.checkedAt)}（北京时间）</p><p>${esc(r.verification||'核验依据未披露')}。入口仅反映核验时状态，不代表当前仍在招。</p><p>来源：${esc(new URL(safeUrl(r.source)).hostname)} · 官网标注日期：${beijingTime(r.sourceUpdated)}</p>${r.lastConfirmedOpen?`<p>最近记录到入口：${beijingTime(r.lastConfirmedOpen)}</p>`:''}<p>${esc(companies[r.company]?.intro||'')}</p><h3>原始摘录</h3><pre>${esc([r.summary,r.experience,r.eligibility,r.jd].filter(Boolean).join('\n\n'))}</pre></details>`;
 box.append(section);updateRecruitmentButtons();section.querySelector('#back-positions').onclick=()=>{section.remove();box.querySelector('.category-top').hidden=false;$('#recruit-results').hidden=false;document.querySelector(`[data-position-open="${id}"]`)?.focus({preventScroll:true});window.scrollTo(0,scroll)};section.querySelector('h2').focus({preventScroll:true});section.scrollIntoView({block:'start'});
}

function savedDetailMarkup(j){
 const summary=recordStage(j)==='summary',d=recruitmentDetail({...j,jd:undefined,summary:undefined}),qual=d.qualifications,grad=qual.filter(t=>/届|毕业/.test(t)),audience=qual.filter(t=>!grad.includes(t)),list=items=>items.length?`<ul>${items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:'<p class="undisclosed">未披露</p>';
 return `<div class="position-detail saved-position-detail"><h3 class="jd-detail-title">${esc(j.title)}</h3><div class="compact-meta">${esc(j.company||'公司未补充')} · ${cityDisplay(j.city)} · ${esc(j.intent||'类型未补充')}</div><div class="saved-tags"><span>${contentLabel(j)}</span><span>${esc(occupationName(j.direction))}</span></div>
 <div class="position-detail-actions saved-detail-actions"><button type="button" id="detail-remove">取消收藏</button>${j.source?`<a class="official-action" href="${esc(safeUrl(j.source))}" target="_blank" rel="noopener noreferrer">前往官网 ↗</a>`:'<span class="muted small">官网来源未补充</span>'}</div>
 <details class="summary-help"><summary>${summary?'招聘官网摘要':'本人保存的 JD'} ⓘ</summary><p>${summary?'当前仅保存招聘摘要，补充原文后可继续整理。':'原文及要求由本人补充和确认。'}未披露不表示不限，个人资格核对不代表招聘方审核。</p></details>
 <div class="position-columns"><div class="position-main"><section><h3>岗位内容</h3><div class="saved-jd-original"><p class="saved-original-text">${esc(j.jd)}</p></div></section><section><h3>整理要求</h3>${j.requirements?.length?`<ul>${j.requirements.map(r=>`<li>${r.kind==='preferred'?'优先':'必需'}：${esc(r.skills.join(r.logic==='any'?' 或 ':'、'))}<p class="small muted">原文依据：${esc(r.quote)}</p></li>`).join('')}</ul>`:'<p class="undisclosed">尚未整理，可从原文核对补充。</p>'}<div class="saved-manage-actions"><button type="button" id="detail-edit">${summary?('补充 JD 原文'):'编辑职位与资料'}</button></div></section></div>
 <section class="position-conditions"><h3>申请条件</h3>${audience.length?`<h4>申请对象</h4>${list(audience)}`:''}${grad.length?`<h4>毕业届别与申请对象</h4>${list(grad)}`:''}${!qual.length?'<p class="undisclosed">未披露</p>':''}<p class="saved-qualification">我的资格核对：${esc(j.qualification||'待确认')}（本人确认）</p>${j.expires?`<p>记录的截止日期：${esc(j.expires)}</p>`:''}<div class="saved-manage-actions">${true?`<button type="button" id="detail-target" data-target="${esc(j.id)}" ${j.archived?'disabled':''}>设为目标岗位</button>`:''}<button type="button" id="detail-apply">加入投递记录</button></div>${j.archived?'<p class="notice">已归档；恢复收藏后可设为目标。</p>':''}</section></div>
 <details class="position-evidence"><summary>来源与核验</summary><p>${j.source?'来源：'+esc(new URL(safeUrl(j.source)).hostname):'来源未补充'}</p><p>原来源检查：${beijingTime(j.sourceCheckedAt||(j.publicId?j.checkedAt:null))}（北京时间）</p><p>${esc(j.verification||j.sourceNotes||'没有独立核验记录；保存或编辑不等于核验在招。')}</p><p>以上为保存时记录，不保证当前仍在招聘。</p><pre>${esc([j.summary,j.experience,j.eligibility].filter(Boolean).join('\n\n'))}</pre></details></div>`;
}
function editLearning(resource=null,key=null){
 const job=state.jobs.find(j=>j.id===state.targetId&&!j.removed&&!j.archived);if(!job){toast('请先从收藏岗位 选择目标岗位');return}
 const old=key?learningItems(state).find(t=>(t.key||t.id)===key):null;
 if(resource&&learningItems(state).some(t=>t.resourceIds?.includes(resource.id))){toast('此资源已在当前目标的计划中，可在任务里编辑学习范围');return}
 modal(old?'编辑学习任务':'加入我的学习计划',`<p>目标：${esc(job.title)}</p>${resource?`<p>资源：${esc(resource.title)}</p>`:''}<label>学习任务<input name="title" required maxlength="150" value="${esc(old?.title||resource?.section||'')}"></label><label>学习主题<input name="skill" required maxlength="60" value="${esc(old?.skill||resource?.skills.join('、')||'')}"></label><label>预计用时（分钟）<input name="minutes" type="number" min="1" required value="${old?.minutes||resource?.minutes||30}" ${old?.status==='完成'?'readonly':''}></label><label>完成目标<textarea name="acceptance" required maxlength="1000" placeholder="例如：解释一个核心概念，完成一个示例并记录验证结果">${esc(old?.acceptance||'')}</textarea></label>${old?`<label>安排日期<input type="date" name="taskDate" value="${esc(old?.date||'')}"></label><label>任务状态<select name="status">${['待做','进行中','完成','暂缓'].map(s=>`<option ${old.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>成果证据<textarea name="evidence" maxlength="4000">${esc(old.evidence||'')}</textarea></label><label class="check"><input type="checkbox" name="accepted" ${old.status==='完成'?'checked':''}>我已核对验收目标并完成实践</label>${(old.resourceIds||[]).map(id=>catalog.find(r=>r.id===id)).filter(Boolean).map(r=>`<p><a href="${r.url}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a></p>`).join('')}`:''}`,f=>{
 const values={date:(f.has('taskDate')?f.get('taskDate'):old?.date)||'',jobId:job.id,title:f.get('title'),skill:f.get('skill'),minutes:Number(f.get('minutes')),acceptance:f.get('acceptance'),resourceIds:old?.resourceIds|| (resource?[resource.id]:[])};const task=createLearningTask(values);
 if(old){if(f.get('status')==='完成'&&(!f.get('accepted')||f.get('evidence').trim().length<10))throw Error('完成任务需要勾选验收并填写至少 10 字成果证据');const current=[...state.tasks,...state.backlog||[]].find(t=>(t.key||t.id)===key&&t.jobId===job.id);if(!current)throw Error('任务已变化，请重新打开');const wasDone=current.status==='完成';Object.assign(current,values,{status:f.get('status'),evidence:f.get('evidence'),completedAt:f.get('status')==='完成'?Date.now():null});if(!wasDone&&current.status==='完成')event('task_completed',current.id||key);if(current.status==='完成'&&!state.tasks.includes(current)){state.backlog=state.backlog.filter(t=>t!==current);state.tasks.push({...current,id:current.id||crypto.randomUUID()})}}
 else{state.tasks.push({...task,date:values.date});event('learning_added',task.id)}
 },'learning:'+(key||resource?.id||'custom')+':'+job.id);
}
function bindLearning(){document.querySelectorAll('[data-learning-edit]').forEach(b=>b.onclick=()=>editLearning(null,b.dataset.learningEdit));document.querySelectorAll('[data-learning-remove]').forEach(b=>b.onclick=async()=>{const key=b.dataset.learningRemove;if(!confirm('将此未完成任务移出当前目标计划？其他岗位和已完成证据会保留。'))return;await mutateSaved(()=>{state.tasks=state.tasks.filter(t=>!(t.jobId===state.targetId&&(t.key||t.id)===key&&t.status!=='完成'));state.backlog=(state.backlog||[]).filter(t=>!(t.jobId===state.targetId&&(t.key||t.id)===key&&t.status!=='完成'));state.activePlan=null;if(state.targetSchedules)delete state.targetSchedules[state.targetId]},render)});document.querySelectorAll('[data-learning-up]').forEach(b=>b.onclick=async()=>{const all=learningItems(state),i=all.findIndex(t=>(t.key||t.id)===b.dataset.learningUp);if(i<1)return;[all[i-1],all[i]]=[all[i],all[i-1]];await mutateSaved(()=>{state.tasks=state.tasks.filter(t=>t.jobId!==state.targetId).concat(all.map(t=>({...t,id:t.id||crypto.randomUUID(),status:t.status||'待做',evidence:t.evidence||''})));state.backlog=(state.backlog||[]).filter(t=>t.jobId!==state.targetId);state.activePlan=null;if(state.targetSchedules)delete state.targetSchedules[state.targetId]},render)})}
function learningLibrary(){const el=document.createElement('section');el.id='learning-library';el.innerHTML=panel('08 / RESOURCE LIBRARY',`<h2>任务资源库 / ${catalog.length} 条</h2><p>覆盖 18 个方向。选择文档或开源项目，填写自己的学习任务，组合成目标计划。</p><div class="filters resource-filters"><label>职业方向<select id="resource-direction"><option value="">全部方向</option>${categories.map(c=>`<option value="${c.id}" ${c.id===state.direction?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><label>类型<select id="resource-type"><option value="">全部</option>${Object.entries(types).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>搜索<input id="resource-query" placeholder="标题或技能"></label></div><p id="resource-count" role="status"></p><div id="resource-results"></div>`);$('main').insertBefore(el,$('.footer'));
 const show=()=>{const rows=catalog.filter(r=>(!$('#resource-direction').value||r.direction===$('#resource-direction').value)&&(!$('#resource-type').value||r.type===$('#resource-type').value)&&[r.title,...r.skills].join(' ').toLowerCase().includes($('#resource-query').value.toLowerCase()));$('#resource-count').textContent=`找到 ${rows.length} 条 / 共 ${catalog.length} 条`;$('#resource-results').innerHTML=rows.map(r=>`<details class="task"><summary>${types[r.type]} / ${esc(r.title)} · ${esc(occupationName(r.direction))}</summary><p>可选学习范围：${esc(r.section)}</p><p>${esc(r.prerequisite)}</p><p class="small">${esc(r.reviewStatus)}${r.reviewedAt?' · '+r.reviewedAt.slice(0,10):''}</p><p class="small">${esc(r.audit?.scope||'未完成章节实践与项目运行验证')} · ${esc(r.license)}</p><div class="filters"><a href="${r.audit?.videoUrl||r.url}" target="_blank" rel="noopener noreferrer">${r.type==='video'?'直接播放（官方MP4）':'原站学习'} ↗</a>${r.type==='video'?`<a href="${r.url}" target="_blank" rel="noopener noreferrer">课程出处 ↗</a>`:''}${r.audit?.guideUrl?`<a href="${r.audit.guideUrl}" target="_blank" rel="noopener noreferrer">修复与运行说明（先阅读）</a>`:''}${r.fallbackId!==r.id?`<a href="${catalog.find(x=>x.id===r.fallbackId)?.url||r.url}" target="_blank" rel="noopener noreferrer">文档替代 ↗</a>`:''}<button data-resource-add="${r.id}" ${!state.targetId||learningItems(state).some(t=>t.resourceIds?.includes(r.id))?'disabled':''}>${learningItems(state).some(t=>t.resourceIds?.includes(r.id))?'已加入计划':'加入目标计划'}</button></div></details>`).join('')||'<p class="empty">暂无匹配资料，请调整筛选条件。</p>';el.querySelectorAll('[data-resource-add]').forEach(b=>b.onclick=()=>editLearning(catalog.find(r=>r.id===b.dataset.resourceAdd)))};$('#resource-direction').onchange=$('#resource-type').onchange=$('#resource-query').oninput=show;show();}

actions.addLearning=()=>editLearning();actions.resources=()=>{activateTab('prep','resources');document.querySelector('#learning-library')?.scrollIntoView({block:'start',behavior:'smooth'})};actions.chooseTarget=()=>{page='jobs';jobsView='saved';render()};


